                start = int(start_str)
                end = file_size
            else:
                # Format: "bytes=100-200" (from byte 100 to 200)
                start = int(start_str)
                end = int(end_str) + 1  # End is inclusive in HTTP range, but exclusive in Python

            # Validate range boundaries
            if start < 0 or start >= file_size:
                raise RangeNotSatisfiable(file_size)

            if end > file_size:
                end = file_size

            if start >= end:
                raise MalformedRangeHeader("Range header: start must be less than end")

            ranges.append((start, end))

